import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as r}from"./app-CtmVft7R.js";var i=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S05/S05E19.html","title":"S05E19 The One Where Ross Can't Flirt","lang":"zh-CN","frontmatter":{"title":"S05E19 The One Where Ross Can't Flirt","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":116},"git":{"createdTime":1780654155000,"updatedTime":1780654155000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":32.24,"words":9673},"filePathRelative":"语言/英语/Friends老友记/S05/S05E19.md"}`),a={name:`S05E19.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-one-where-ross-can-t-flirt" tabindex="-1"><a class="header-anchor" href="#the-one-where-ross-can-t-flirt"><span>The One Where Ross Can&#39;t Flirt</span></a></h1><blockquote><p><em>罗斯不能调情的那一集</em></p></blockquote><p>The One Where Ross Can&#39;t Flirt</p><blockquote><p>罗斯不能调情的那个</p></blockquote><p><strong>Written by: Doty Abrams</strong></p><blockquote><p>作者：多蒂·艾布拉姆斯</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s, Chandler is getting ready for a date with Monica as Ross enters.</em></p><blockquote><p>🎬 <em>钱德勒和乔伊家，罗斯进来时，钱德勒正准备和莫妮卡约会。</em></p></blockquote><p><strong>Ross Geller:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Chandler Bing:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Ross Geller:</strong> Wow! You look nice. What&#39;s the occasion?</p><blockquote><p>哇！你看起来不错。什么场合？</p></blockquote><p><strong>Chandler Bing:</strong> Monica and I are celebrating our ten-month anniversary, we&#39;ve got reservations at Ja George.</p><blockquote><p>我和莫妮卡正在庆祝我们结婚十个月的纪念日，我们在乔治酒店预订了房间。</p></blockquote><p><strong>Ross Geller:</strong> Wow! How&#39;d you get in there?</p><blockquote><p>哇！你怎么进去的？</p></blockquote><p><strong>Chandler Bing:</strong> Made a few calls, pulled some strings, and they agreed to seat us at 11:30 if we both had the chicken and didn&#39;t get desert.</p><blockquote><p>打了几个电话，拉了些关系，他们同意在11:30给我们安排座位，如果我们都吃了鸡肉而没有吃到甜点的话。</p></blockquote><p><em>(There&#39;s a knock on the door and Chandler answers it. It&#39;s the pizza delivery girl.)</em></p><blockquote><p><em>（有人敲门，钱德勒应门，是送比萨饼的女孩。）</em></p></blockquote><p><strong>Delivery Girl:</strong> Hi Chandler!</p><blockquote><p>嗨，钱德勒！</p></blockquote><p><strong>Chandler Bing:</strong> Hey Caitlin! Somebody got a haircut.</p><blockquote><p>嘿，凯特琳！有人理发了。</p></blockquote><p><strong>Caitlin:</strong> Ugh, I hate it! I look like an 8-year-old boy.</p><blockquote><p>啊，我讨厌它！我看起来像个8岁的男孩。</p></blockquote><p><strong>Chandler Bing:</strong> Yeah, if that was true, gym class would&#39;ve been a lot more interesting.</p><blockquote><p>是的，如果那是真的，体育课会有趣得多。</p></blockquote><p><strong>Caitlin:</strong> It&#39;s uh, 27 dollars even.</p><blockquote><p>嗯，27美元。</p></blockquote><p><strong>Chandler Bing:</strong> Oh, okay. (Hands her the money.) Here you go.</p><blockquote><p>哦，好的。（把钱递给她。）给你。</p></blockquote><p><em>(The duck starts quacking.)</em></p><blockquote><p><em>（鸭子开始嘎嘎作响。）</em></p></blockquote><p><strong>Caitlin:</strong> Hey, where&#39;s the chicken?</p><blockquote><p>嘿，鸡在哪里？</p></blockquote><p><strong>Chandler Bing:</strong> Oh, he&#39;s in the back. The duck pissed him off, said that eggs came first.</p><blockquote><p>哦，他在后面。鸭子惹他生气了，说鸡蛋是第一位的。</p></blockquote><p><strong>Caitlin:</strong> (laughs) Great. I&#39;ll see you later!</p><blockquote><p>（笑）太好了。待会儿见！</p></blockquote><p><strong>Chandler Bing:</strong> Okay, bye!</p><blockquote><p>好的，再见！</p></blockquote><p><em>(He closes the door and turns to see Ross glaring at him.)</em></p><blockquote><p><em>（他关上门，转身看到罗斯怒视着他。）</em></p></blockquote><p><strong>Ross Geller:</strong> What the hell was that?!</p><blockquote><p>那他妈的是什么？！</p></blockquote><p><strong>Chandler Bing:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Ross Geller:</strong> The flirting! Aren&#39;t you supposed to be going out with, I don&#39;t know hmm, let&#39;s say my sister?!</p><blockquote><p>调情！我不知道，你不是应该和我妹妹出去吗？！</p></blockquote><p><strong>Chandler Bing:</strong> I was not flirting.</p><blockquote><p>我不是在调情。</p></blockquote><p><strong>Ross Geller:</strong> It was totally flirting. &quot;Somebody got a haircut (Makes some whiney, nasally noises.)&quot;</p><blockquote><p>那完全是调情。“有人剪了头发（发出一些呜呜声、鼻音）。”</p></blockquote><p><strong>Chandler Bing:</strong> Okay first of all, the impression, uncanny. And second, that was not flirting, that was just casual conversation between two people. That is all.</p><blockquote><p>好吧，首先，印象，不可思议。其次，那不是调情，那只是两个人之间的随意交谈。仅此而已。</p></blockquote><p><strong>Ross Geller:</strong> Yeah, right.</p><blockquote><p>是的，对。</p></blockquote><p><strong>Chandler Bing:</strong> You wanna see flirting? I&#39;ll show you flirting. (Starts to move towards Ross.)</p><blockquote><p>你想看调情吗？我给你看调情。（开始向罗斯走去。）</p></blockquote><p><strong>Ross Geller:</strong> (backing away) I&#39;m good.</p><blockquote><p>（后退）我很好。</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Rachel and Phoebe are in the kitchen.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋的，瑞秋和菲比在厨房。</em></p></blockquote><p><strong>Rachel Green:</strong> I am so proud of Joey, I can&#39;t believe he&#39;s going to be on Law &amp; Order!</p><blockquote><p>我真为乔伊感到骄傲，真不敢相信他会上治安课！</p></blockquote><p><strong>Phoebe Buffay:</strong> I know. But don&#39;t you think that it should be called Order and Law?</p><blockquote><p>我知道。但是你不认为它应该被称为秩序和法律吗？</p></blockquote><p><strong>Rachel Green:</strong> No because first they arrest the guy and then they try him.</p><blockquote><p>不，因为他们先逮捕那个人，然后审判他。</p></blockquote><p><strong>Phoebe Buffay:</strong> Don&#39;t get me started on that.</p><blockquote><p>别让我这么开始。</p></blockquote><p><em>(Ross and Chandler enter with the pizzas.)</em></p><blockquote><p><em>（罗斯和钱德勒拿着比萨饼进来。）</em></p></blockquote><p><strong>Chandler Bing:</strong> I was not flirting.</p><blockquote><p>我不是在调情。</p></blockquote><p><strong>Ross Geller:</strong> And on your anniversary, for shame!</p><blockquote><p>在你的周年纪念日，真丢脸！</p></blockquote><p><strong>Rachel Green:</strong> What&#39;s going on?</p><blockquote><p>发生什么事了？</p></blockquote><p><strong>Ross Geller:</strong> Chandler was hitting on the hot delivery girl!</p><blockquote><p>钱德勒在和那个性感的送货女搭讪！</p></blockquote><p><strong>Chandler Bing:</strong> I was not and oh God, shh!</p><blockquote><p>我不是，哦，天哪，嘘！</p></blockquote><p><strong>Ross Geller:</strong> Well I&#39;m sorry but you were! Okay? And besides if anyone should be hitting on her it&#39;s the guy who&#39;s single, the guy that who-who-who can do something about it.</p><blockquote><p>很抱歉，你是！可以此外，如果有人想勾引她，那就是那个单身的男人，那个能做点什么的男人。</p></blockquote><p><strong>Phoebe Buffay:</strong> Sounds like somebody wants to be Mr. Pizza Delivery Girl.</p><blockquote><p>听起来好像有人想当送比萨饼的小姐。</p></blockquote><p><strong>Ross Geller:</strong> Well…</p><blockquote><p>嗯…</p></blockquote><p><strong>Chandler Bing:</strong> Is that what this is about? You like Caitlin?</p><blockquote><p>这就是为什么？你喜欢凯特琳？</p></blockquote><p><em>(Ross looks at Rachel.)</em></p><blockquote><p><em>（罗斯看着瑞秋。）</em></p></blockquote><p><strong>Rachel Green:</strong> Ross! We broke up two years ago; you&#39;ve been married since then. I think it&#39;s okay that we see other people.</p><blockquote><p>罗斯！我们两年前分手了；从那以后你就结婚了。我想我们见到其他人没关系。</p></blockquote><p><strong>Ross Geller:</strong> Well, I-I was watching her the other day at the pizza place.</p><blockquote><p>嗯，前几天我在比萨饼店看着她。</p></blockquote><p><strong>Rachel Green:</strong> Hm-mmm.</p><blockquote><p>嗯。</p></blockquote><p><strong>Ross Geller:</strong> And she&#39;s just so sexy and funny and has the cutest little…</p><blockquote><p>而且她很性感，很有趣，有一个最可爱的小女孩…</p></blockquote><p><strong>Rachel Green:</strong> Okay, y&#39;know what? We don&#39;t need her measurements.</p><blockquote><p>好吧，你知道吗？我们不需要她的尺寸。</p></blockquote><p><strong>Phoebe Buffay:</strong> (looking through the pizzas) Okay pepperoni, pepperoni, pepperoni, okay Ross, I know she&#39;s pretty and you love her, but is she stupid?! She forgot my vegetarian!</p><blockquote><p>（看着比萨饼）好的意大利香肠，意大利香肠，意大利香肠，好的罗斯，我知道她很漂亮，你爱她，但她愚蠢吗？！她忘了我的素食者！</p></blockquote><p><strong>Ross Geller:</strong> This is perfect! She&#39;ll have to come back here with your pizza, and when she does, I&#39;ll turn on the Charm-O-Ross. Oh I&#39;m so glad you don&#39;t eat meat.</p><blockquote><p>这太完美了！她会带着你的披萨回来的，等她回来的时候，我会打开魔咒。哦，我很高兴你不吃肉。</p></blockquote><p><strong>Phoebe Buffay:</strong> See? Vegetarianism benefits everyone.</p><blockquote><p>看到了吗？素食主义对每个人都有好处。</p></blockquote><p><strong>Joey Tribbiani:</strong> (entering, with his grandmother) Hey everybody, look who&#39;s here! You remember my grandmother!</p><blockquote><p>（和他的祖母一起进来）嘿，大家看看谁来了！你还记得我的祖母！</p></blockquote><p><strong>Rachel Green:</strong> Big night!</p><blockquote><p>大夜晚！</p></blockquote><p><strong>Phoebe Buffay:</strong> This is so cool!</p><blockquote><p>这太酷了！</p></blockquote><p><strong>Chandler Bing:</strong> So, Joey on Law &amp; Order, you must be very proud!</p><blockquote><p>那么，法律与秩序方面的乔伊，你一定很自豪吧！</p></blockquote><p><strong>Joey Tribbiani:</strong> Chandler, she doesn&#39;t understand a word of English.</p><blockquote><p>钱德勒，她一个英语字都不懂。</p></blockquote><p><strong>Chandler Bing:</strong> I&#39;m sorry, I thought you were Joey&#39;s other grandmother. (She just stares at him.) I&#39;ve done it again.</p><blockquote><p>对不起，我以为你是乔伊的另一个祖母。（她只是盯着他）我又做了一次。</p></blockquote><p><strong>Joey Tribbiani:</strong> She&#39;s my biggest fan. Yeah, she&#39;s the only one in the family that&#39;s believed in me.</p><blockquote><p>她是我最大的粉丝。是的，她是家里唯一相信我的人。</p></blockquote><p><em>(They both start speaking Italian to each other, and since I&#39;m not Italian and don&#39;t understand one word, we&#39;ll move on to the English portion of the show. Not, that I&#39;m English. Not that there&#39;s anything wrong with that, it&#39;s just that I&#39;m not. Y&#39;know I think I should shut-up now and move on. Anyhoo, she says something about Joey being fat I think based on this line.)</em></p><blockquote><p><em>（他们开始互相说意大利语，既然我不是意大利人，一个字也听不懂，我们就转到节目的英语部分。不是说我是英国人。不是说这有什么问题，只是我不是。你知道，我想我现在应该闭嘴，继续说下去。不管怎样，她说乔伊胖我瘦k基于此行。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah, I uh weighted like 27 pounds when I was born so…</p><blockquote><p>是的，我出生时体重27磅，所以…</p></blockquote><p><strong>Monica Geller:</strong> (entering from the bathroom) Hey! Happy Anniversary!</p><blockquote><p>（从浴室进来）嘿！周年快乐！</p></blockquote><p><strong>Chandler Bing:</strong> Happy Anniversary, 10 months! (They kiss.)</p><blockquote><p>周年快乐，10个月！（他们接吻。）</p></blockquote><p><strong>Monica Geller:</strong> So umm, when I was in the shower I was thinking about our first night in London…</p><blockquote><p>嗯，当我洗澡的时候，我在想我们在伦敦的第一个晚上…</p></blockquote><p><strong>Chandler Bing:</strong> Uhh, Joey&#39;s grandmother is right there. (Points)</p><blockquote><p>嗯，乔伊的祖母就在那里。（点数）</p></blockquote><p><strong>Monica Geller:</strong> Is that the one that speaks English or the one that doesn&#39;t?</p><blockquote><p>是那个会说英语的还是那个不会说英语的？</p></blockquote><p><strong>Chandler Bing:</strong> The one that doesn&#39;t.</p><blockquote><p>那个没有。</p></blockquote><p><strong>Monica Geller:</strong> That was some hot love you gave me! I&#39;m gonna go get ready.</p><blockquote><p>那是你给我的热恋！我去准备一下。</p></blockquote><p><strong>Chandler Bing:</strong> Hey, why don&#39;t you wear those earrings I gave you?</p><blockquote><p>嘿，你为什么不戴我给你的耳环呢？</p></blockquote><p><strong>Monica Geller:</strong> That&#39;s a great idea! I was saving them for something special.</p><blockquote><p>好主意！我把它们留着做些特别的事。</p></blockquote><p><strong>Chandler Bing:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Monica Geller:</strong> (runs over to Phoebe) You have got to go home!</p><blockquote><p>（跑向菲比）你必须回家！</p></blockquote><p><strong>Phoebe Buffay:</strong> But I like it here!</p><blockquote><p>但我喜欢这里！</p></blockquote><p><strong>Monica Geller:</strong> You gotta go home and get the earrings that you borrowed from me okay? Chandler wants me to wear them tonight.</p><blockquote><p>你得回家去拿你从我这里借的耳环，好吗？钱德勒要我今晚穿。</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay, well I think that they&#39;re in my purse. Why don&#39;t you go get dressed and I&#39;ll look for them.</p><blockquote><p>好吧，我想它们在我的钱包里。你为什么不去穿衣服，我去找他们。</p></blockquote><p><strong>Monica Geller:</strong> Great!</p><blockquote><p>太好了！</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay! (Walks over to Rachel) Rach, hi, I need those earrings you borrowed.</p><blockquote><p>好的！（走向瑞秋）瑞秋，嗨，我需要你借的耳环。</p></blockquote><p><strong>Rachel Green:</strong> Oh, umm, okay, yeah, I&#39;ll be, yeah I&#39;ll be right back. (Goes to her room.)</p><blockquote><p>哦，嗯，好的，是的，我会的，是的，我马上回来。（去她的房间。）</p></blockquote><p><em>(Phoebe then gets possessed &#39;cause she starts speaking in tongues. She speaks Italian to Joey&#39;s grandmother. She is quickly exorcised and returns to speaking in English. Of course, too most people English is a strange language as well. But none of them are probably reading this and if they were they wouldn&#39;t understand it. So why am I talking about them? I have absolutely no clue. Moving on…)</em></p><blockquote><p><em>（菲比开始说方言，所以她着魔了。她对乔伊的祖母说意大利语。她很快被驱魔，又开始说英语。当然，大多数人英语也是一种奇怪的语言。但他们中可能没有一个人在读这篇文章，如果他们是的话，他们也不会理解。那么我为什么要说英语呢是他们吗？我完全不知道。继续…）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Wow Pheebs, you speak Italian?</p><blockquote><p>哇，菲比，你会说意大利语吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> I guess so. (See, the brief possession didn&#39;t affect her at all, like we could really tell.)</p><blockquote><p>我想是的。（看，这一短暂的占有对她一点影响都没有，就像我们可以说的那样。）</p></blockquote><p><strong>Rachel Green:</strong> (She enters and hands Phoebe the earring) Here you go. Thank you!</p><blockquote><p>（她进来把耳环递给菲比）给你。非常感谢。</p></blockquote><p><strong>Phoebe Buffay:</strong> Wait, Rach! Where&#39;s the other one?</p><blockquote><p>等等，瑞秋！另一个在哪里？</p></blockquote><p><strong>Rachel Green:</strong> Oh what, you-you want both of them?</p><blockquote><p>哦，什么，你想要两个？</p></blockquote><p><strong>Phoebe Buffay:</strong> Rachel Karen Green, where&#39;s the other earring?!</p><blockquote><p>瑞秋·凯伦·格林，另一只耳环呢？！</p></blockquote><p><strong>Rachel Green:</strong> Okay, okay, okay, look, just don&#39;t freak out, but I kinda lost it. I know it&#39;s in the apartment, but I definitely lost it.</p><blockquote><p>好吧，好吧，好吧，听着，别紧张，但我有点失去了它。我知道它在公寓里，但我肯定把它弄丢了。</p></blockquote><p><strong>Phoebe Buffay:</strong> Well, what am I going to tell Monica? She wants to wear them tonight!</p><blockquote><p>那么，我该怎么跟莫妮卡说呢？她今晚想穿它们！</p></blockquote><p><strong>Rachel Green:</strong> Tell her to wear her own earrings.</p><blockquote><p>告诉她戴她自己的耳环。</p></blockquote><p><strong>Phoebe Buffay:</strong> These are her earrings.</p><blockquote><p>这是她的耳环。</p></blockquote><p><strong>Rachel Green:</strong> Nooo! Nooooo! You lent me Monica&#39;s earrings?! I&#39;m not allowed to borrow her stuff!</p><blockquote><p>不！不！你借给我莫妮卡的耳环？！我不能借她的东西！</p></blockquote><p><strong>Phoebe Buffay:</strong> Why not?</p><blockquote><p>为什么不呢？</p></blockquote><p><strong>Rachel Green:</strong> Because I lose her stuff!</p><blockquote><p>因为我丢了她的东西！</p></blockquote><p>⏱ <em>Time Lapse, the gang is now watching Law &amp; Order. By the way, the entire rest of the episode takes place in Monica and Rachel&#39;s apartment. Why are they called apartments when they&#39;re all stuck together? Something to think about.</em></p><blockquote><p>⏱ <em>随着时间的推移，这帮人现在正在看《法律与秩序》。顺便说一句，这一集的其余部分都发生在莫妮卡和瑞秋的公寓里。为什么他们在一起的时候被称为公寓？需要考虑一下。</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Okay, see that blind guy right there? I&#39;m gonna bash his head in later.</p><blockquote><p>好的，看到那个盲人了吗？我等会儿要打他的头。</p></blockquote><p><em>(His grandmother asks him something.)</em></p><blockquote><p><em>（他的祖母问了他一些问题。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Oh umm, my big scene is coming up. Big scene coming up.</p><blockquote><p>哦，嗯，我的大场景就要开始了。大场面即将到来。</p></blockquote><p><strong>Chandler Bing:</strong> If you said, &quot;Big lima bean, bubbling up.&quot; Would she understand the difference?</p><blockquote><p>如果你说，“大利马豆，冒着气泡。”她会理解其中的区别吗？</p></blockquote><p><strong>Monica Geller:</strong> (noticing Rachel crawling behind the couch) Rach? What are you doing?</p><blockquote><p>（注意到瑞秋在沙发后面爬）瑞秋？你在做什么？</p></blockquote><p><strong>Rachel Green:</strong> Oh boy, I just can&#39;t watch. It&#39;s too scary!</p><blockquote><p>哦，孩子，我就是不能看。太可怕了！</p></blockquote><p><strong>Monica Geller:</strong> It&#39;s a diaper commercial.</p><blockquote><p>这是尿布广告。</p></blockquote><p><strong>Rachel Green:</strong> Oh yeah well, you know me, babies, responsibilities, ahhh!!!</p><blockquote><p>哦，是的，你知道我，宝贝，责任，啊！！！</p></blockquote><p><em>(There&#39;s a knock on the door.)</em></p><blockquote><p><em>（有人敲门。）</em></p></blockquote><p><strong>Caitlin:</strong> Pizza delivery!</p><blockquote><p>披萨送货！</p></blockquote><p><strong>Ross Geller:</strong> I&#39;ll get it! I will get that! (Runs over and opens the door.)</p><blockquote><p>我去拿！我会得到的！（跑过去开门。）</p></blockquote><p><strong>Caitlin:</strong> Hi!</p><blockquote><p>嗨！</p></blockquote><p><strong>Ross Geller:</strong> Hi!</p><blockquote><p>嗨！</p></blockquote><p><strong>Caitlin:</strong> One uh, vegetarian pizza. That&#39;s $12.15.</p><blockquote><p>一个，嗯，素食比萨饼。12.15美元。</p></blockquote><p><strong>Ross Geller:</strong> Oh. Uh, by the way, if it makes you feel any better. I happen to like 8-year-old boys.</p><blockquote><p>哦。嗯，顺便说一下，如果这能让你感觉好些的话。我碰巧喜欢8岁的男孩。</p></blockquote><p><strong>Caitlin:</strong> What?!</p><blockquote><p>什么？！</p></blockquote><p><strong>Ross Geller:</strong> (I can&#39;t make it out.) The uh, your hair, before, your hair, you said you thought your looks like an 8-year-old&#39;s, and I&#39;m just saying I like it. The hair.</p><blockquote><p>（我搞不懂）呃，你的头发，以前，你的头发，你说你觉得你看起来像个8岁的孩子，我只是说我喜欢。头发。</p></blockquote><p><strong>Caitlin:</strong> Oh. Thanks.</p><blockquote><p>哦。谢谢</p></blockquote><p><strong>Ross Geller:</strong> You understand I don&#39;t actually like 8-year-old boys.</p><blockquote><p>你知道我其实不喜欢8岁的男孩。</p></blockquote><p><strong>Caitlin:</strong> Y&#39;know, all I&#39;m looking for is the money.</p><blockquote><p>你知道，我只是在找钱。</p></blockquote><p><strong>Chandler Bing:</strong> Here you go. (Hands her the money.) Now stop bringing us pizzas you.</p><blockquote><p>给你。（把钱递给她）现在别再给我们送比萨饼了。</p></blockquote><p><strong>Caitlin:</strong> I&#39;m gonna try. (Walks away and Ross closes the door.)</p><blockquote><p>我要试试。（罗斯走开，关上门。）</p></blockquote><p><strong>Chandler Bing:</strong> You&#39;re welcome.</p><blockquote><p>不客气。</p></blockquote><p><strong>Ross Geller:</strong> You couldn&#39;t let me have her, could ya?!</p><blockquote><p>你不能让我拥有她，是吗？！</p></blockquote><p><strong>Chandler Bing:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Ross Geller:</strong> This is a girl that I really like and had too swoop in there!</p><blockquote><p>这是一个我非常喜欢的女孩，而且在那里也很抢眼！</p></blockquote><p><strong>Monica Geller:</strong> What&#39;s goin&#39; on?</p><blockquote><p>怎么了？</p></blockquote><p><strong>Ross Geller:</strong> Chandler was totally flirting with the hot delivery girl!</p><blockquote><p>钱德勒完全是在和那个性感的女送货员调情！</p></blockquote><p><strong>Chandler Bing:</strong> Thank you for that! (To Monica) I was not flirting.</p><blockquote><p>谢谢你！（对莫妮卡）我不是在调情。</p></blockquote><p><strong>Monica Geller:</strong> It&#39;s okay. I don&#39;t care. It&#39;s uh, it&#39;s fine.</p><blockquote><p>没关系。我不在乎。没事。</p></blockquote><p><strong>Ross Geller:</strong> Really?!</p><blockquote><p>真的吗？！</p></blockquote><p><strong>Chandler Bing:</strong> Really?!</p><blockquote><p>真的吗？！</p></blockquote><p><strong>Monica Geller:</strong> It&#39;s no big deal, I do it all the time.</p><blockquote><p>没什么大不了的，我一直都这么做。</p></blockquote><p><strong>Chandler Bing:</strong> (starts to laugh, but then gets serious) So umm, you-you flirt with guys all the time?</p><blockquote><p>（开始笑，但后来变得严肃起来）那么，嗯，你总是和男人调情？</p></blockquote><p><strong>Monica Geller:</strong> Sure! It doesn&#39;t mean anything! Just like I know it doesn&#39;t mean anything with you!</p><blockquote><p>当然！这没有任何意义！就像我知道的，这对你没有任何意义！</p></blockquote><p><strong>Chandler Bing:</strong> Okay, but there is a big difference. You are a lot hotter than I am.</p><blockquote><p>好吧，但是有很大的不同。你比我性感多了。</p></blockquote><p><strong>Joey Tribbiani:</strong> (walking past) True story! (Goes and sits down.)</p><blockquote><p>（走过）真实的故事！（走过去坐下。）</p></blockquote><p><strong>Monica Geller:</strong> Chandler, this actually bothers you?</p><blockquote><p>钱德勒，这真的让你烦恼吗？</p></blockquote><p><strong>Chandler Bing:</strong> Yes, it does bother me! And I think it would bother a lot of people. Rachel, when you were going out with Ross, did it bother you when he flirted with other women?</p><blockquote><p>是的，我真的很烦！我想这会困扰很多人。瑞秋，当你和罗斯约会的时候，他和其他女人调情的时候，你有没有感到困扰？</p></blockquote><p><strong>Rachel Green:</strong> Uhh, no, no, it bothered me when he slept with other women.</p><blockquote><p>哦，不，不，当他和其他女人上床的时候，我很烦恼。</p></blockquote><p><strong>Ross Geller:</strong> And thank you, for that.</p><blockquote><p>谢谢你，谢谢你。</p></blockquote><p><strong>Rachel Green:</strong> But y&#39;know, I never really had anything to worry about. Ross was never very good at the flirting thing.</p><blockquote><p>但是你知道，我从来没有什么好担心的。罗斯从不擅长调情。</p></blockquote><p><strong>Ross Geller:</strong> What? (Mumbles) What-what, what are talking about? It-it worked with you.</p><blockquote><p>什么？（咕哝）你在说什么？它和你一起工作。</p></blockquote><p><strong>Rachel Green:</strong> Oh! Y&#39;know what? You&#39;re right! We meet, you flirted and then bamn nine years later you had me!</p><blockquote><p>哦！你知道吗？你说得对！我们相遇，你调情，九年后你拥有了我！</p></blockquote><p><strong>Ross Geller:</strong> All right, all right. You-you-you know what I&#39;m going to do? I am going to order another pizza and when Caitlin gets here, you-you--I will show how well I flirt. Yeah! I will, I will get her phone number! (To Chandler) And not the one on the menu!</p><blockquote><p>好吧，好吧。你知道我要做什么吗？我要再点一份比萨饼，等凯特琳来的时候，你我会展示我的调情能力。是 啊我会的，我会得到她的电话号码！（对钱德勒）而不是菜单上的那个！</p></blockquote><p><strong>Phoebe Buffay:</strong> (entering from Rachel&#39;s bedroom) I found it!</p><blockquote><p>（从瑞秋的卧室进来）我找到了！</p></blockquote><p><strong>Rachel Green:</strong> Ohh! Thank God! Where was it?</p><blockquote><p>哦！感谢上帝！它在哪里？</p></blockquote><p><strong>Phoebe Buffay:</strong> On your dresser.</p><blockquote><p>在你的梳妆台上。</p></blockquote><p><strong>Rachel Green:</strong> Okay that is the one we already have!</p><blockquote><p>好的，我们已经有了！</p></blockquote><p><strong>Joey Tribbiani:</strong> Okay, here&#39;s my big scene. My big scene&#39;s here! (They have two of the cops on the street, then they cut to where they&#39;re entering an apartment.) Oh my God.</p><blockquote><p>好吧，这是我的大场景。我的大场景在这里！（他们有两个警察在街上，然后他们切到要进入公寓的地方。）哦，天哪。</p></blockquote><p><strong>Monica Geller:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> (smiling) Okay, everybody just keep smiling. It&#39;ll kill my grandmother if she finds out.</p><blockquote><p>（微笑）好吧，大家都保持微笑。如果我祖母发现了，她会死的。</p></blockquote><p><strong>Chandler Bing:</strong> (smiling) Well, what is it?</p><blockquote><p>（微笑）那是什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> (smiling) Oh, they cut me out of the show.</p><blockquote><p>（微笑）哦，他们把我从节目中删掉了。</p></blockquote><p><strong>Rachel Green:</strong> (smiling) What?!</p><blockquote><p>（微笑）什么？！</p></blockquote><p><strong>Ross Geller:</strong> (smiling) Are you sure?</p><blockquote><p>（微笑）你确定吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> (smiling) Maybe your scene&#39;s coming up?</p><blockquote><p>（微笑）也许你的戏就要上演了？</p></blockquote><p><strong>Joey Tribbiani:</strong> (smiling) Not likely. &#39;Cause you see that body bag right there</p><blockquote><p>（微笑）不太可能因为你看到那个尸体袋了吗</p></blockquote><p><strong>Rachel Green:</strong> (smiling) Yeah.</p><blockquote><p>（微笑）是的。</p></blockquote><p><strong>Joey Tribbiani:</strong> (smiling) I&#39;m in it.</p><blockquote><p>（微笑）我在里面。</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, it&#39;s continued from before the commercial break.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋的，从广告前就开始了。</em></p></blockquote><p><strong>Phoebe Buffay:</strong> (smiling) This is terrible, what are you going to do?</p><blockquote><p>（微笑）这太糟糕了，你打算怎么办？</p></blockquote><p><strong>Joey Tribbiani:</strong> (smiling) I don&#39;t know. This little, old lady lives for my career. When they dumped me off of Days of Our Lives she almost died.</p><blockquote><p>（微笑）我不知道。这个小老太太为我的事业而活。当他们把我从我们的生活中甩出去的时候，她差点死了。</p></blockquote><p><strong>Phoebe Buffay:</strong> (not smiling) That&#39;s not good.</p><blockquote><p>（不笑）那不好。</p></blockquote><p><strong>Joey Tribbiani:</strong> (smiling) No, smile! Not that face, smile! Everybody smile! (They all smile.)</p><blockquote><p>（微笑）不，微笑！不是那张脸，微笑！大家都笑！（他们都笑了。）</p></blockquote><p><strong>Rachel Green:</strong> (smiling) Joey, why don&#39;t you just tell her what happened? It&#39;s not your fault.</p><blockquote><p>（微笑）乔伊，你为什么不告诉她发生了什么事？这不是你的错。</p></blockquote><p><strong>Chandler Bing:</strong> (smiling) If we keep talking this way, aren&#39;t we gonna freak her out soon?</p><blockquote><p>（微笑）如果我们继续这样说话，我们不是很快就会吓坏她吗？</p></blockquote><p><strong>Grandma Tribbiani:</strong> (Something in Italian to Joey.)</p><blockquote><p>（用意大利语对乔伊说。）</p></blockquote><p><strong>Joey Tribbiani:</strong> Soon, soon, I&#39;m gonna be on soon. There I am! (Points to the screen, of course it isn&#39;t him.)</p><blockquote><p>很快，很快，我很快就要上场了。我来了！（指着屏幕，当然不是他。）</p></blockquote><p><strong>Grandma Tribbiani:</strong> (pointing at the screen) No! Sam Waterston!</p><blockquote><p>（指着屏幕）不！山姆·沃特斯顿！</p></blockquote><p><strong>Joey Tribbiani:</strong> No-no-no, that-that&#39;s me, that&#39;s me.</p><blockquote><p>不不不，那是我，那是我。</p></blockquote><p><strong>Grandma Tribbiani:</strong> No, it&#39;s Sam Waterston! Crimes and Misdemeanors, Capricorn One.</p><blockquote><p>不，是山姆·沃特斯顿！犯罪和轻罪，摩羯座一号。</p></blockquote><p><strong>Chandler Bing:</strong> Doesn&#39;t know, &quot;Hello.&quot; But she knows Capricorn One.</p><blockquote><p>不知道“你好”，但她知道摩羯座一号。</p></blockquote><p><em>(Phoebe gets up.)</em></p><blockquote><p><em>（菲比站了起来。）</em></p></blockquote><p><strong>Monica Geller:</strong> (following her) Phoebe! I have to have those earrings, we&#39;re going to leave as soon as the show is over.</p><blockquote><p>（跟着她）菲比！我得带上那些耳环，演出一结束我们就走。</p></blockquote><p><strong>Phoebe Buffay:</strong> But I already gave them back to you!</p><blockquote><p>但我已经把它们还给你了！</p></blockquote><p><strong>Monica Geller:</strong> No you didn&#39;t.</p><blockquote><p>不，你没有。</p></blockquote><p><strong>Phoebe Buffay:</strong> All right, I already didn&#39;t give them back to you, that&#39;s what I said. (Walks away over to Rachel.) Where is that other earring?</p><blockquote><p>好吧，我已经没有还给你了，我就是这么说的。（走向瑞秋）另一只耳环在哪里？</p></blockquote><p><strong>Rachel Green:</strong> It&#39;s not here Pheebs, it&#39;s not here. Ohh, I went to Joey and Chandler&#39;s last night! Okay! (Goes to the door.)</p><blockquote><p>不在这儿，菲比，不在这儿。哦，我昨晚去了乔伊和钱德勒家！可以（走到门口。）</p></blockquote><p><strong>Phoebe Buffay:</strong> Make sure you check Chandler&#39;s jewelry box.</p><blockquote><p>一定要检查钱德勒的首饰盒。</p></blockquote><p><strong>Rachel Green:</strong> Wait a minute. Chandler has a jewelry box?</p><blockquote><p>等一下。钱德勒有珠宝盒吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay, we have like ten minutes. Do you want me to get into that now?!</p><blockquote><p>好的，我们大概有十分钟。你想让我现在就开始吗？！</p></blockquote><p><em>(Rachel heads for Joey and Chandler&#39;s and Phoebe heads for the kitchen to find Ross.)</em></p><blockquote><p><em>（瑞秋走向乔伊和钱德勒家，菲比走向厨房去找罗斯。）</em></p></blockquote><p><strong>Ross Geller:</strong> (To Phoebe) Hey Pheebs! How&#39;s that uh, vegetarian pizza working out for ya? You and those vegetables have a real thing going on, huh?</p><blockquote><p>（对菲比）嘿，菲比！素食披萨对你来说怎么样？你和那些蔬菜真的发生了什么事？</p></blockquote><p><strong>Phoebe Buffay:</strong> (she just looks at him) Why are you being weird?</p><blockquote><p>（她只是看着他）你为什么这么奇怪？</p></blockquote><p><strong>Ross Geller:</strong> Do you like it?</p><blockquote><p>你喜欢吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> No, that would be, &quot;Why are you being cute?&quot;</p><blockquote><p>不，那会是，“你为什么这么可爱？”</p></blockquote><p><strong>Ross Geller:</strong> Okay, I&#39;m working on my flirting.</p><blockquote><p>好吧，我正在努力调情。</p></blockquote><p><strong>Phoebe Buffay:</strong> Ohh! I did not get that.</p><blockquote><p>哦！我不明白。</p></blockquote><p>[Cut to Chandler and Monica on the couch.]</p><blockquote><p>[切到沙发上的钱德勒和莫妮卡。]</p></blockquote><p><strong>Chandler Bing:</strong> So uh Monica, do you, do you like the Law &amp; Order?</p><blockquote><p>莫妮卡，你，你喜欢法律和秩序吗？</p></blockquote><p><strong>Monica Geller:</strong> Yeah, it&#39;s good.</p><blockquote><p>是的，很好。</p></blockquote><p><strong>Chandler Bing:</strong> See, I&#39;m finding out all this stuff about you today, like you like the Law &amp; Order and that you flirted with every guy in the Tri-State area!</p><blockquote><p>看，我今天发现了所有关于你的事情，比如你喜欢法律与秩序，你和三州地区的每个男人都调情！</p></blockquote><p><strong>Monica Geller:</strong> Chandler! (Joey and his grandmother shush them and wave them away, which they do.) Okay, let me get this straight, it&#39;s okay for you to flirt, but not for me.</p><blockquote><p>钱德勒！（乔伊和他的祖母嘘了他们一声，挥手示意他们走开，他们就是这么做的。）好吧，让我说清楚，你可以调情，但我不行。</p></blockquote><p><strong>Chandler Bing:</strong> Oh, I&#39;m so glad we cleared that up. Look, I&#39;m sorry, some things are different for men and for women.</p><blockquote><p>哦，我很高兴我们澄清了这一点。听着，对不起，有些事情对男人和女人是不同的。</p></blockquote><p><strong>Monica Geller:</strong> Go on, teach me something about men and women.</p><blockquote><p>继续，教我一些关于男人和女人的知识。</p></blockquote><p><strong>Chandler Bing:</strong> Okay, I&#39;ve already taught you so much already, but whatever. See when you flirt with a guy you think, &quot;I&#39;m just flirting, no big deal.&quot; But the guy is thinking, &quot;Finally! Somebody who wants to sleep with me!&quot;</p><blockquote><p>好吧，我已经教了你很多了，但不管怎样。看，当你和一个男人调情时，你会想，“我只是在调情，没什么大不了的。”但这个男人在想，“终于有人想和我上床了！”</p></blockquote><p><strong>Monica Geller:</strong> No way!</p><blockquote><p>不可能！</p></blockquote><p><strong>Chandler Bing:</strong> It&#39;s true.</p><blockquote><p>是真的。</p></blockquote><p><strong>Monica Geller:</strong> Well that&#39;s pathetic!</p><blockquote><p>那太可悲了！</p></blockquote><p><strong>Chandler Bing:</strong> Again true.</p><blockquote><p>又是真的。</p></blockquote><p><strong>Monica Geller:</strong> And this goes for all guys?</p><blockquote><p>这对所有男人都适用？</p></blockquote><p><strong>Chandler Bing:</strong> All guys that are awake. Then we go to sleep and then all the guys from the other end of the world wake up and behave the exact same way.</p><blockquote><p>所有醒着的人。然后我们睡觉，然后所有来自世界另一端的人醒来，表现完全一样。</p></blockquote><p><strong>Joey Tribbiani:</strong> (To Ross in the kitchen) All right, it&#39;s another commercial; I still haven&#39;t told her!</p><blockquote><p>（对厨房里的罗斯）好吧，这是另一个广告；我还没告诉她！</p></blockquote><p><strong>Ross Geller:</strong> Joey! This is like the last commercial. You&#39;ve got like (checks his watch) ten minutes left!</p><blockquote><p>乔伊！这就像上次的广告一样。你（看他的表）还有十分钟！</p></blockquote><p><strong>Joey Tribbiani:</strong> I know, I know! What am I going to do? (Thinks) Ooh!</p><blockquote><p>我知道，我知道！我该怎么办？（想）哦！</p></blockquote><p><strong>Monica Geller:</strong> No! You are not gonna run out and leave her here!</p><blockquote><p>不！你不能跑出去把她留在这里！</p></blockquote><p><strong>Joey Tribbiani:</strong> (dejected) Yeah, all right. (Thinks of something.) Ooh! (He quickly runs out before anyone can stop him.)</p><blockquote><p>（沮丧地）是的，好吧。（想了想）哦！（他很快就跑了出去，没人能阻止他。）</p></blockquote><p><strong>Grandma Tribbiani:</strong> Joey!</p><blockquote><p>乔伊！</p></blockquote><p><strong>Chandler Bing:</strong> Uh, Joey is gonna be right back. Right back! (Tries to pantomime it for her.) Meanwhile, let&#39;s-let&#39;s-let&#39;s talk about you. (Pause.) So, you&#39;re old and small.</p><blockquote><p>呃，乔伊马上就回来。右后卫！（试着为她表演）同时，让我们谈谈你。（停顿）那么，你又老又小。</p></blockquote><p>⏱ <em>Time lapse, Rachel is coming back from Chandler and Joey&#39;s.</em></p><blockquote><p>[时间流逝，瑞秋从钱德勒和乔伊家回来了。]</p></blockquote><p><strong>Rachel Green:</strong> (entering) (To Phoebe) (whispering) Hey!</p><blockquote><p>（进来）（对菲比）（耳语）嘿！</p></blockquote><p><strong>Phoebe Buffay:</strong> Did you find it?</p><blockquote><p>你找到了吗？</p></blockquote><p><strong>Rachel Green:</strong> The earring? No. But look, I found my sunglasses under the couch! I&#39;ve been looking for these since like last summer. (Puts &#39;em on.)</p><blockquote><p>耳环？没有。但是你看，我在沙发下面找到了我的太阳镜！从去年夏天开始我就一直在找这些。（戴上。）</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay, those are my sunglasses, you borrowed them from me.</p><blockquote><p>好吧，那是我的太阳镜，你从我这里借的。</p></blockquote><p><strong>Rachel Green:</strong> Okay, calm down, here they are. (Gives back the sunglasses.)</p><blockquote><p>好了，冷静点，他们在这儿。（把太阳镜还给我。）</p></blockquote><p><strong>Monica Geller:</strong> (entering from her room) Phoebe! (Motions for the earrings. Phoebe gives her the one-minute sign.)</p><blockquote><p>（从她的房间进来）菲比！（为耳环做手势。菲比给了她一分钟的手势。）</p></blockquote><p><strong>Phoebe Buffay:</strong> (To Rachel) What are we going to do?!</p><blockquote><p>（对瑞秋）我们该怎么办？！</p></blockquote><p><strong>Rachel Green:</strong> I don&#39;t know, I don&#39;t know.</p><blockquote><p>我不知道，我不知道。</p></blockquote><p><strong>Phoebe Buffay:</strong> All right well, we&#39;re just gonna have to tell Monica, that&#39;s all.</p><blockquote><p>好吧，我们得告诉莫妮卡，就这样。</p></blockquote><p><strong>Rachel Green:</strong> Oh gosh, she&#39;s going to kill me.</p><blockquote><p>哦，天哪，她要杀了我。</p></blockquote><p><strong>Phoebe Buffay:</strong> I suppose I could tell her it&#39;s just all my fault.</p><blockquote><p>我想我可以告诉她这都是我的错。</p></blockquote><p><strong>Rachel Green:</strong> Ohh that&#39;d be great!</p><blockquote><p>哦，那太好了！</p></blockquote><p><strong>Phoebe Buffay:</strong> Mon, can I talk to you for a sec?</p><blockquote><p>莫恩，我能和你谈谈吗？</p></blockquote><p><strong>Monica Geller:</strong> Yeah, what is it?</p><blockquote><p>是的，是什么？</p></blockquote><p><strong>Phoebe Buffay:</strong> Umm, I lost one of your earrings. I&#39;m sorry! I am so, so sorry!</p><blockquote><p>嗯，我丢了你的一只耳环。我很抱歉！我非常非常抱歉！</p></blockquote><p><strong>Monica Geller:</strong> (shocked) Wow! All right well, I mean, what can you do? If you lost it you lost it.</p><blockquote><p>（震惊）哇！好吧，我是说，你能做什么？如果你把它弄丢了，你就把它弄丢了。</p></blockquote><p><strong>Phoebe Buffay:</strong> I will replace it, I promise. I feel so terrible.</p><blockquote><p>我会换的，我保证。我感觉很糟糕。</p></blockquote><p><strong>Monica Geller:</strong> All right, sweetie that&#39;s fine. You didn&#39;t do it on purpose.</p><blockquote><p>好吧，亲爱的，没关系。你不是故意的。</p></blockquote><p><strong>Phoebe Buffay:</strong> No.</p><blockquote><p>没有。</p></blockquote><p><strong>Monica Geller:</strong> Look at you! Come here! (They hug.) Feel better?</p><blockquote><p>看看你！过来！（他们拥抱）感觉好点了吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah! You&#39;re the best!</p><blockquote><p>是啊！你是最棒的！</p></blockquote><p><strong>Rachel Green:</strong> Okay, wait a minute. Wait a minute, I-I-I, I can&#39;t do this. Listen honey, this is, it&#39;s not Phoebe&#39;s fault. She lent me the earrings, and I lost it. I&#39;m so sorry. Honey, I feel terrible too. (Holds out her arms for a hug.)</p><blockquote><p>好的，等一下。等等，我，我，我不能这么做。听着，亲爱的，这不是菲比的错。她把耳环借给我，我把它弄丢了。我很抱歉。亲爱的，我也很难受。（伸出双臂拥抱。）</p></blockquote><p><strong>Monica Geller:</strong> (angrily) That is exactly why I do not lend you stuff!! (Rachel looks over at Phoebe in resignation.) Okay?! I mean, first it&#39;s my jewelry! And if it&#39;s not my jewelry, it&#39;s-it&#39;s my blue sweater! And if it&#39;s not my sweater, it&#39;s my sunglasses!</p><blockquote><p>（愤怒地）这正是我不借给你东西的原因！！（瑞秋看着辞职的菲比）好吗？！我是说，首先是我的珠宝！如果不是我的珠宝，那是我的蓝色毛衣！如果不是我的毛衣，那就是我的太阳镜！</p></blockquote><p><strong>Rachel Green:</strong> Your sunglasses?!</p><blockquote><p>你的太阳镜？！</p></blockquote><p><strong>Monica Geller:</strong> Yes!</p><blockquote><p>是的！</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, right! (Hands Monica back her sunglasses.)</p><blockquote><p>哦，对了！（把莫妮卡的太阳镜还给她。）</p></blockquote><p><strong>Caitlin:</strong> (from outside) Pizza!</p><blockquote><p>（从外面）比萨饼！</p></blockquote><p><strong>Ross Geller:</strong> (running to the door) Oh, mine! Mine! Mine! (to everyone) Okay, here goes. Prepare yourselves for some Class A flirting.</p><blockquote><p>（跑向门口）哦，我的！矿矿（对大家）好了，开始吧。准备一些A级调情。</p></blockquote><p><strong>Chandler Bing:</strong> Okay, hold on. (Pauses as he readies himself.) Okay. (Walks away.)</p><blockquote><p>好的，等一下。（他准备好时停顿了一下）好的。（走开了。）</p></blockquote><p><strong>Rachel Green:</strong> Honey, you have nothing to prove. And if you really like this girl, I don&#39;t flirting is the right thing to… (Ross interrupts and shushes her.)</p><blockquote><p>亲爱的，你没有什么可以证明的。如果你真的喜欢这个女孩，我不认为调情是正确的…（罗斯打断她，嘘了她一声。）</p></blockquote><p><strong>Ross Geller:</strong> You&#39;ll see. Okay. (Readies himself.) Oh, what&#39;s-what&#39;s her name?</p><blockquote><p>你会明白的。可以（准备好了）哦，她叫什么名字？</p></blockquote><p><strong>All:</strong> Caitlin!</p><blockquote><p>凯特琳！</p></blockquote><p><strong>Grandma Tribbiani:</strong> Caitlin!</p><blockquote><p>凯特琳！</p></blockquote><p><strong>Ross Geller:</strong> (He opens the door while faking a laugh.) Hey! Oh, we-we can&#39;t keep eating like this. (Monica turns her head in shame.)</p><blockquote><p>（他假装笑着开门。）嘿！哦，我们不能再这样吃下去了。（莫妮卡羞愧地转过头。）</p></blockquote><p><strong>Caitlin:</strong> It&#39;s uh, $12.50.</p><blockquote><p>嗯，12.50美元。</p></blockquote><p><strong>Ross Geller:</strong> Okay, (gets the money) so, do you make the pizzas in one of those uh, wood-burning ovens?</p><blockquote><p>好的，（拿到钱）那么，你是用烧木头的烤箱做比萨饼的吗？</p></blockquote><p><strong>Caitlin:</strong> No actually umm, I think that they&#39;re umm, gas.</p><blockquote><p>不，事实上，嗯，我想它们是嗯，汽油。</p></blockquote><p><strong>Ross Geller:</strong> Gas? Wow! Intense.</p><blockquote><p>汽油？哇！强烈的</p></blockquote><p><strong>Chandler Bing:</strong> (To Monica) If this is the way all the Gellers flirt, we don&#39;t have a problem.</p><blockquote><p>（对莫妮卡）如果这是所有盖勒人调情的方式，我们没有问题。</p></blockquote><p><strong>Ross Geller:</strong> (to Caitlin) Hey uh, y&#39;know that smell gas has?</p><blockquote><p>（对凯特琳）嘿，你知道煤气的味道吗？</p></blockquote><p><strong>Caitlin:</strong> (wanting more than anything to get the money and leave this horrible, horrible place) Yeah.</p><blockquote><p>（想得到更多的钱，离开这个可怕的地方）是的。</p></blockquote><p><strong>Ross Geller:</strong> They put that in.</p><blockquote><p>他们把它放进去了。</p></blockquote><p><strong>Caitlin:</strong> What?!</p><blockquote><p>什么？！</p></blockquote><p><strong>Ross Geller:</strong> The gas is odorless, but they add the smell so you know when there&#39;s a leak.</p><blockquote><p>煤气是无味的，但它们会增加气味，这样你就知道什么时候有泄漏了。</p></blockquote><p><strong>Caitlin:</strong> (getting more desperate to leave) Well okay!</p><blockquote><p>（越来越想离开）好吧！</p></blockquote><p><strong>Ross Geller:</strong> A lot of other gas smells…</p><blockquote><p>还有很多其他的煤气味…</p></blockquote><p><strong>Chandler Bing:</strong> Oh the humanity.</p><blockquote><p>哦，人性。</p></blockquote><p><strong>Ross Geller:</strong> Meth-methane smells…</p><blockquote><p>甲基甲烷闻起来…</p></blockquote><p><strong>Caitlin:</strong> Y&#39;know what umm, actually I, I really, I should go.</p><blockquote><p>你知道吗，嗯，实际上我，我真的，我该走了。</p></blockquote><p><strong>Ross Geller:</strong> Oh but I-I-I haven&#39;t paid you yet!</p><blockquote><p>哦，但我还没付你钱呢！</p></blockquote><p><strong>Caitlin:</strong> Y&#39;know what? That&#39;s okay, you guys have ordered so many that this one is on me! (Runs for her life.)</p><blockquote><p>你知道吗？没关系，你们订了这么多，我请客！（为了她的生命而奔跑。）</p></blockquote><p><em>(Ross closes the door slowly.)</em></p><blockquote><p><em>（罗斯慢慢地关上门。）</em></p></blockquote><p><strong>Ross Geller:</strong> (To All) Was I talking to her about gas?</p><blockquote><p>（对大家）我是在跟她谈汽油吗？</p></blockquote><p><strong>Chandler Bing:</strong> More so than anything else.</p><blockquote><p>比什么都重要。</p></blockquote><p><strong>Phoebe Buffay:</strong> I-I-I found it interesting.</p><blockquote><p>我觉得很有趣。</p></blockquote><p><strong>Rachel Green:</strong> I&#39;m sorry.</p><blockquote><p>对不起。</p></blockquote><p><strong>Ross Geller:</strong> Look, no-no, hey, hey, don&#39;t worry about it! In nine years, she and I will be right there. (Goes and sits on the couch dejectedly.)</p><blockquote><p>听着，不，不，嘿，嘿，别担心！九年后，她和我就在那里。（沮丧地走过去坐在沙发上。）</p></blockquote><p><strong>Rachel Green:</strong> Okay, well, I&#39;m gonna clear out some of these boxes. (She grabs a couple of the old pizza boxes and exits.)</p><blockquote><p>好吧，好吧，我要清理一些箱子。（她抓起两个旧比萨饼盒，走出去。）</p></blockquote><p><strong>Phoebe Buffay:</strong> (walking over to Ross) Ross?</p><blockquote><p>（走向罗斯）罗斯？</p></blockquote><p><strong>Ross Geller:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> What else do they add smell too?</p><blockquote><p>它们还能增加什么味道？</p></blockquote><hr><p>🎬 <em>The street outside the building, Rachel is running to catch up with Caitlin.</em></p><blockquote><p>🎬 <em>大楼外的街道，瑞秋正跑去追赶凯特琳。</em></p></blockquote><p><strong>Rachel Green:</strong> Hey! Hey! (Stops Caitlin) Hi! Hey-hey-hey, I&#39;m Rachel! From upstairs? The ones with all the pizza?</p><blockquote><p>嘿！嘿（凯特琳停下来）嗨！嘿，嘿，我是瑞秋！从楼上？那些有所有比萨饼的？</p></blockquote><p><strong>Caitlin:</strong> Oh, is there a problem?</p><blockquote><p>哦，有什么问题吗？</p></blockquote><p><strong>Rachel Green:</strong> No. No. Every thing&#39;s--they&#39;re fine. Great pizza. But it&#39;s uh, actually umm my friend Ross. He uh, just gets really nervous when he&#39;s flirting.</p><blockquote><p>不，不，一切都很好。很棒的比萨饼。但实际上是我的朋友罗斯。他在调情的时候真的很紧张。</p></blockquote><p><strong>Caitlin:</strong> Oh my God! That was flirting?!</p><blockquote><p>哦，我的天啊！那是调情？！</p></blockquote><p><strong>Rachel Green:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Caitlin:</strong> Wow!</p><blockquote><p>哇！</p></blockquote><p><strong>Rachel Green:</strong> I know, I know, but uh just, I&#39;m telling you, once, once you get past that part, that where it-it just feels like you wanna die, he&#39;s-he&#39;s really a good person.</p><blockquote><p>我知道，我知道，但是，呃，我只是告诉你，一旦，一旦你过了那个阶段，你就会觉得你想死，他，他真的是个好人。</p></blockquote><p><strong>Caitlin:</strong> The guy with the gas?!</p><blockquote><p>那个拿煤气的家伙？！</p></blockquote><p><strong>Rachel Green:</strong> Yeah. I&#39;m-I&#39;m telling you he&#39;s really sweet and he&#39;s really funny and he&#39;s just ugh, got a good heart. And besides, I y&#39;know, I think he really likes you.</p><blockquote><p>是的。我告诉你，他真的很可爱，很有趣，他只是有一颗善良的心。而且，我知道，我觉得他真的很喜欢你。</p></blockquote><p><strong>Caitlin:</strong> Really?!</p><blockquote><p>真的吗？！</p></blockquote><p><strong>Rachel Green:</strong> Well y&#39;know, we have 7 people and like 10 pizzas, what do you think?</p><blockquote><p>嗯，你知道，我们有7个人，像10个披萨，你觉得怎么样？</p></blockquote><p><strong>Caitlin:</strong> I just, I thought Joey was there.</p><blockquote><p>我只是，我以为乔伊在那里。</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Phoebe, Chandler, and Joey&#39;s grandmother are still watching Law &amp; Order.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋、菲比、钱德勒和乔伊的祖母还在看《法律与秩序》。</em></p></blockquote><p><strong>Rachel Green:</strong> (entering) Hey Ross? Umm, I just ran into Caitlin in the hallway and-and uh, you must be getting better at this flirting stuff than I thought.</p><blockquote><p>（进来）嘿，罗斯？嗯，我刚在走廊里遇到凯特琳，你在调情方面一定比我想象的要好。</p></blockquote><p><strong>Ross Geller:</strong> What do you mean?</p><blockquote><p>你什么意思？</p></blockquote><p><strong>Rachel Green:</strong> Well, I don&#39;t get it, but she wanted me to give you her phone number. (Hands him the slip of paper with the phone number on it.)</p><blockquote><p>我不明白，但她想让我给你她的电话号码。（把写着电话号码的纸条递给他。）</p></blockquote><p><strong>Ross Geller:</strong> And she just gave you this?</p><blockquote><p>她刚刚给了你这个？</p></blockquote><p><strong>Rachel Green:</strong> Yeah!</p><blockquote><p>是啊！</p></blockquote><p><strong>Ross Geller:</strong> Rach, thanks but uh, I don&#39;t need you doing me any favors.</p><blockquote><p>瑞秋，谢谢，不过我不需要你帮我什么忙。</p></blockquote><p><strong>Rachel Green:</strong> I-I-I didn&#39;t! I didn&#39;t! She thought you were cute.</p><blockquote><p>我，我，我没有！我没有！她觉得你很可爱。</p></blockquote><p><strong>Ross Geller:</strong> Well that I can believe.</p><blockquote><p>我可以相信。</p></blockquote><p><strong>Rachel Green:</strong> Yay!</p><blockquote><p>耶！</p></blockquote><p><strong>Joey Tribbiani:</strong> (entering) Hey! Is the show still on?</p><blockquote><p>（进来）嘿！节目还在继续吗？</p></blockquote><p><strong>Chandler Bing:</strong> Almost over man.</p><blockquote><p>快结束了，伙计。</p></blockquote><p><strong>Joey Tribbiani:</strong> (says hi to his grandma) Look! Oh! (Pointing out the window.) Is that the Pope?! (Chandler and his grandma turn to look and Joey slips a tape into the VCR.)</p><blockquote><p>（向他奶奶打招呼）看！哦（指着窗外）是教皇吗？！（钱德勒和他的奶奶转过头去看，乔伊把一盘磁带塞进了录像机。）</p></blockquote><p><strong>Chandler Bing:</strong> Why am I looking?</p><blockquote><p>我为什么要看？</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, here I am, here&#39;s my big scene!</p><blockquote><p>哦，我来了，这是我的大场景！</p></blockquote><p><em>(Joey has made a little home movie that&#39;s his big scene. He braces himself against the door to his apartment and while holding a plastic gun and wearing the same sweater says…)</em></p><blockquote><p><em>（乔伊拍了一部家庭小电影，这是他的大场景。他紧靠着公寓的门，拿着一把塑料枪，穿着同样的毛衣说……）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> (on the tape) All right back off! I gotta gun! I&#39;m not afraid to use it!</p><blockquote><p>（在磁带上）好了，退后！我有枪！我不怕用它！</p></blockquote><p><strong>Grandma Tribbiani:</strong> Oh Joey!</p><blockquote><p>哦，乔伊！</p></blockquote><p><strong>Joey Tribbiani:</strong> That&#39;s right!</p><blockquote><p>没错！</p></blockquote><p><strong>Chandler Bing:</strong> You couldn&#39;t have at least changed your shirt.</p><blockquote><p>你至少不能换你的衬衫。</p></blockquote><p><strong>Joey Tribbiani:</strong> (on the tape) Now, I wanna a suitcase filled with 100,000 dollars. (The duck quacks, to the duck) Choo! Choo! Choo! (To the imaginary cops) Filled with $100,000 in small bills, and if I don&#39;t get it…(the duck quacks louder) Choo!! And if I don&#39;t get it, (pause, picks up the duck) I&#39;m gonna shoot this duck!</p><blockquote><p>（在磁带上）现在，我想要一个装满10万美元的手提箱。（鸭子呱呱叫着，对鸭子说）呜！呜！呜！（对想象中的警察）装满了10万美元的小钞票，如果我拿不到的话…（鸭子嘎嘎地叫）呜！！如果我不明白，（停顿一下，捡起鸭子）我要射死这只鸭子！</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh no!</p><blockquote><p>哦，不！</p></blockquote><p><strong>Joey Tribbiani:</strong> (on the tape) I&#39;m comin&#39; out! (He opens the door and hops out pointing the gun in all directions and then runs out of view.)</p><blockquote><p>（在磁带上）我要出去了！（他打开门，跳了出来，把枪指向各个方向，然后跑出了视野。）</p></blockquote><p><strong>Ross Geller:</strong> (To Phoebe) And she&#39;s supposed to buy this?!</p><blockquote><p>（对菲比）她应该买这个吗？！</p></blockquote><p><strong>Grandma Tribbiani:</strong> Joey, bravo! (Starts with that Italian stuff again.)</p><blockquote><p>乔伊，太棒了！（又从意大利菜开始了。）</p></blockquote><p><em>(Suddenly, the tape cuts away from Joey&#39;s impromptu scene, to Chandler standing really, really close to the camera.)</em></p><blockquote><p><em>（突然，录像带从乔伊的即兴表演中消失了，钱德勒站在离摄像机非常非常近的地方。）</em></p></blockquote><p><strong>Chandler Bing:</strong> (singing) Ground control to Major Tom! Commencing countdown…engines…on!</p><blockquote><p>（唱）地面控制呼叫汤姆少校！开始倒计时…引擎…打开！</p></blockquote><p><em>(Joey and Chandler both run to shut off the tape.)</em></p><blockquote><p><em>（乔伊和钱德勒都跑去关掉磁带。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> (to his grandmother) That&#39;s uh, scenes from next week&#39;s show. Next week&#39;s!</p><blockquote><p>（对他的祖母）那是下周演出的场景。下周的！</p></blockquote><p><strong>Phoebe Buffay:</strong> I am definitely gonna watch that!</p><blockquote><p>我一定会看的！</p></blockquote><p>Ending Credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, another time lapse, Monica is seeking advice from Rachel and Phoebe about possible replacement earrings.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋的，又过了一段时间，莫妮卡正在寻求瑞秋和菲比关于可能更换耳环的建议。</em></p></blockquote><p><strong>Monica Geller:</strong> What about these? These look the same?</p><blockquote><p>这些怎么样？这些看起来一样吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Definitely!</p><blockquote><p>当然！</p></blockquote><p><strong>Monica Geller:</strong> Not as each other!</p><blockquote><p>彼此不一样！</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, then no.</p><blockquote><p>哦，那就不行了。</p></blockquote><p><em>(Goes over to Chandler.)</em></p><blockquote><p><em>（走向钱德勒。）</em></p></blockquote><p><strong>Chandler Bing:</strong> (To Monica) Hey!</p><blockquote><p>（对莫妮卡）嘿！</p></blockquote><p><strong>Monica Geller:</strong> Hi!</p><blockquote><p>嗨！</p></blockquote><p><strong>Chandler Bing:</strong> You ready?</p><blockquote><p>准备好了吗？</p></blockquote><p><strong>Monica Geller:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Chandler Bing:</strong> You look amazing. I&#39;m the luckiest man in the world.</p><blockquote><p>你看起来棒极了。我是世界上最幸运的人。</p></blockquote><p><strong>Monica Geller:</strong> Ohh, you&#39;re about to get a little luckier.</p><blockquote><p>哦，你会更幸运的。</p></blockquote><p><strong>Chandler Bing:</strong> Let me see the earrings.</p><blockquote><p>让我看看耳环。</p></blockquote><p><strong>Monica Geller:</strong> Oh, honey, the earrings…</p><blockquote><p>哦，亲爱的，耳环…</p></blockquote><p><strong>Chandler Bing:</strong> (looking at them) They look great! Does your boyfriend have the best taste or what?</p><blockquote><p>（看着他们）他们看起来很棒！你男朋友最有品味吗？</p></blockquote><p><strong>Monica Geller:</strong> My boyfriend really does have good taste!</p><blockquote><p>我男朋友真的很有品味！</p></blockquote><p><em>(He turns to get his coat and Monica gives Rachel and Phoebe two thumbs up as Chandler walks over to Ross.)</em></p><blockquote><p><em>（他转过身去拿外套，莫妮卡竖起两个大拇指，钱德勒走向罗斯。）</em></p></blockquote><p><strong>Chandler Bing:</strong> (To Ross) Thanks for picking out the earrings man.</p><blockquote><p>（对罗斯）谢谢你挑选耳环。</p></blockquote><p><strong>Ross Geller:</strong> Hm-mmm.</p><blockquote><p>嗯。</p></blockquote><p>contrl08.gif (14783 bytes)</p><blockquote><p>contrl08.gif（14783字节）</p></blockquote>`,678)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};